import {parseCSV,buildEntries} from './narration.js';
import {openOffice,extractOffice} from './office.js';
export {parseCSV,speakSymbols,narrate,speechChunks} from './narration.js';
const MAX_TEXT=500000;
function textBlocks(text){const blocks=[];let pending=[];const flush=()=>{if(pending.length){blocks.push({kind:'paragraph',text:pending.join('\n')});pending=[]}};const lines=text.replace(/\r\n?/g,'\n').split('\n');for(let i=0;i<lines.length;i++){const line=lines[i].trim();if(!line){flush();continue}const heading=line.match(/^(#{1,6})\s+(.*)/);if(heading){flush();blocks.push({kind:'heading',level:heading[1].length,text:heading[2]});continue}if(line.includes('|')&&/^\s*\|?\s*:?-{2,}/.test(lines[i+1]||'')){flush();const row=s=>s.trim().replace(/^\|/,'').replace(/\|$/,'').split(/(?<!\\)\|/).map(v=>v.replace(/\\\|/g,'|').trim());const rows=[row(line)];i+=2;while(i<lines.length&&lines[i].includes('|'))rows.push(row(lines[i++]));i--;blocks.push({kind:'table',rows});continue}if(line.includes('\t')){flush();const rows=[];while(i<lines.length&&lines[i].includes('\t'))rows.push(lines[i++].split('\t'));i--;blocks.push({kind:'table',rows});continue}pending.push(line)}flush();return blocks}
export function finishResult(name,blocks,header,warnings=[],sample=false){const entries=buildEntries(blocks,header,name,warnings);return{name,blocks,headers:header,entries,paragraphs:entries.map(e=>e.text),warnings,sample,coverage:{tables:blocks.filter(b=>b.kind==='table').length,structured:blocks.filter(b=>['차트 데이터','연결선 구조','도식 구조'].includes(b.method)).length,visuals:blocks.filter(b=>b.kind==='visual').length,unresolved:blocks.filter(b=>b.unresolved).length,ocr:blocks.filter(b=>b.ocrText).length,layout:blocks.filter(b=>b.layoutText).length,unreadable:blocks.filter(b=>b.kind==='visual'&&b.unresolved&&!b.ocrText).length}}}
export async function convertFile(file,header=true,options={}){if(!(file instanceof Blob)||!file.size)throw Error('비어 있는 파일입니다.');if(file.size>20*1024*1024)throw Error('20 MB 이하의 파일을 선택해 주세요.');const ext=file.name.split('.').pop().toLowerCase(),warnings=new Set();let blocks;options.progress?.('문서 구조를 읽는 중');
 if(['txt','md','csv'].includes(ext)){let text;const bytes=await file.arrayBuffer();try{text=new TextDecoder('utf-8',{fatal:true}).decode(bytes)}catch{text=new TextDecoder('euc-kr').decode(bytes);warnings.add('한국어 문자 인코딩으로 읽었습니다. 글자가 바르게 표시되는지 확인해 주세요.')}if(text.length>MAX_TEXT)throw Error('50만 자 이하로 자료를 나눠 주세요.');if(ext==='csv'){const rows=parseCSV(text);if(!rows.length)throw Error('데이터가 없는 CSV입니다.');blocks=[{kind:'table',rows}];if(rows.some(r=>r.length!==rows[0].length))warnings.add('CSV의 행별 열 개수가 다릅니다. 없는 칸은 빈 값으로 읽습니다.')}else blocks=textBlocks(text)
 }else if(['docx','pptx'].includes(ext))blocks=extractOffice(await openOffice(file),ext,warnings);else if(ext==='pdf'){const {pdfBlocks}=await import('./pdf-reader.js');blocks=await pdfBlocks(file,warnings,options)}else throw Error('PDF, DOCX, PPTX, CSV, TXT, MD 파일을 선택해 주세요.');
 if(options.signal?.aborted)throw new DOMException('취소했습니다.','AbortError');
 if(!blocks.length)throw Error('읽을 수 있는 내용이 없습니다.');const size=blocks.reduce((s,b)=>s+(b.text?.length||0)+(b.rows?.flat().join('').length||0),0);if(size>MAX_TEXT||blocks.length>5000)throw Error('문서 내용이 너무 많습니다. 자료를 나눠 주세요.');
 if(blocks.some(b=>b.kind==='visual')){const {processVisuals}=await import('./vision.js');await processVisuals(blocks,options,warnings)}
 return finishResult(file.name,blocks,header,[...warnings]);
}
